mapper.sql:
s.tab_type = 'active' AND s.strategy_class = '重点客群' AND s.is_deleted = 0
AND s.strategy_id != '999' AND s.channel != '全部'
AND s.big_category != '全部' AND s.small_category != '全部'
AND EXISTS (SELECT 1 FROM t_sr_strategy cg
    WHERE cg.strategy_code = s.strategy_id AND cg.tab_type = 'active'
      AND cg.strategy_class = '重点客群' AND cg.is_deleted = 0
      AND cg.customer_group = #{query.customerGroup})
AND s.city_id = #{query.cityId}
AND s.county_id = #{query.countyId}
AND s.channel = #{query.channel}
AND s.big_category = #{query.bigCategory}
AND s.small_category = #{query.smallCategory}
AND s.strategy_name LIKE CONCAT('%', #{query.strategyName}, '%')
AND s.stat_month >= DATE_SUB(CONCAT(#{query.statMonth}, '-01'), INTERVAL 12 MONTH)
AND s.stat_month < DATE_ADD(CONCAT(#{query.statMonth}, '-01'), INTERVAL 1 MONTH)
